parameters.functionCode:
const pools = $input.item.json.data || [];

// Filter and rank pools
const filteredPools = pools
  .filter(pool => {
    return pool.apy > 5 && // Minimum 5% APY
           pool.tvlUsd > 1000000 && // Min $1M TVL
           pool.il7d < 2 && // Low impermanent loss
           !pool.project.toLowerCase().includes('scam')
  })
  .sort((a, b) => {
    // Score = APY * (1 - IL_risk) * log(TVL)
    const scoreA = a.apy * (1 - (a.il7d || 0) / 100) * Math.log10(a.tvlUsd);
    const scoreB = b.apy * (1 - (b.il7d || 0) / 100) * Math.log10(b.tvlUsd);
    return scoreB - scoreA;
  })
  .slice(0, 20);

return filteredPools.map(pool => ({
  json: {
    pool_id: pool.pool,
    chain: pool.chain,
    project: pool.project,
    symbol: pool.symbol,
    apy: pool.apy,
    tvl_usd: pool.tvlUsd,
    il_7d: pool.il7d || 0,
    reward_tokens: pool.rewardTokens || [],
    pool_meta: pool.poolMeta || '',
    timestamp: new Date().toISOString()
  }
}));

