parameters.functionCode:
const poolData = $input.item.json;
const analysis = JSON.parse($('GPT-4 - Analyze Pool Risk').item.json.choices[0].message.content);

// Calculate risk-adjusted return
const riskMultiplier = analysis.risk_rating === 'low' ? 1.0 : 
                        analysis.risk_rating === 'medium' ? 0.7 : 0.4;
const adjustedAPY = poolData.apy * riskMultiplier;

const optimizedPool = {
  optimization_id: `opt_${Date.now()}`,
  timestamp: new Date().toISOString(),
  pool: {
    id: poolData.pool_id,
    chain: poolData.chain,
    project: poolData.project,
    symbol: poolData.symbol,
    apy: poolData.apy,
    tvl_usd: poolData.tvl_usd
  },
  metrics: {
    raw_apy: poolData.apy,
    risk_adjusted_apy: adjustedAPY.toFixed(2),
    impermanent_loss_7d: poolData.il_7d,
    tvl_score: Math.log10(poolData.tvl_usd).toFixed(2)
  },
  ai_analysis: analysis,
  recommended_action: analysis.recommendation === 'strong_buy' || analysis.recommendation === 'buy'
};

return { json: optimizedPool };

